// @FIGURE_CODE_BEGIN
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
document.getElementById('container').appendChild(canvas);

var PKA1 = 2.34, PKA2 = 9.69, PI = 6.01;
var currentEq = 1;
var netChargeView = false;
var selectedLandmark = 'pI';
var hitRegions = [];
var currentStep = 0;

var demoSteps = [
  {
    title: 'Start fully protonated',
    narration: 'At very low equivalents of added base, alanine is mostly fully protonated: the amino group is H3N+ and the carboxyl group is COOH, giving a net positive charge.',
    state: { baseEquivalents: 0, rightPanelView: 'Species' }
  },
  {
    title: 'First buffering point',
    narration: 'At 0.5 equivalents, the curve passes through pKa1 = 2.34. This is a 50:50 mixture of fully protonated alanine and the zwitterion, because the carboxyl proton is half removed.',
    state: { baseEquivalents: 0.5, rightPanelView: 'Species' }
  },
  {
    title: 'Isoelectric zwitterion',
    narration: 'At 1.0 equivalent, alanine is mostly the zwitterion H3N+CH(CH3)COO−. The positive ammonium and negative carboxylate charges cancel, so the net charge is zero.',
    state: { baseEquivalents: 1, rightPanelView: 'Net charge' }
  },
  {
    title: 'Second buffering point',
    narration: 'At 1.5 equivalents, the curve reaches pKa2 = 9.69. The zwitterion and fully deprotonated anion are present in equal amounts as the ammonium proton is half removed.',
    state: { baseEquivalents: 1.5, rightPanelView: 'Species' }
  },
  {
    title: 'End fully deprotonated',
    narration: 'Near 2.0 equivalents, alanine is mostly H2NCH(CH3)COO−. Both acidic protons have been removed, leaving the molecule with a net negative charge.',
    state: { baseEquivalents: 2, rightPanelView: 'Net charge' }
  }
];

function nbarFromPH(pH) {
  var ka1 = Math.pow(10, -PKA1), ka2 = Math.pow(10, -PKA2);
  var h = Math.pow(10, -pH);
  var d = h * h + ka1 * h + ka1 * ka2;
  return (ka1 * h + 2 * ka1 * ka2) / d;
}

function pHFromEq(eq) {
  if (eq <= 0) return 0;
  if (eq >= 2) return 11.6;
  var lo = -0.2, hi = 12.2;
  for (var i = 0; i < 70; i++) {
    var mid = (lo + hi) / 2;
    if (nbarFromPH(mid) < eq) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

function activeRegion() {
  if (currentEq < 0.25) return 'low';
  if (currentEq < 0.75) return 'pKa1';
  if (currentEq < 1.25) return 'pI';
  if (currentEq < 1.75) return 'pKa2';
  return 'high';
}

function update_baseEquivalents(v) {
  currentEq = Math.max(0, Math.min(2, v));
  selectedLandmark = activeRegion();
  var out = document.getElementById('baseEquivalentsVal');
  if (out) out.value = currentEq.toFixed(2);
  if (chart) chart.update('none');
}

function toggle_rightPanelView(on) {
  netChargeView = !!on;
  var lab = document.getElementById('rightPanelViewVal');
  if (lab) lab.textContent = netChargeView ? 'Net charge' : 'Species';
  if (chart) chart.update('none');
}

function prevStep() {
  goToStep(Math.max(0, currentStep - 1));
}

function nextStep() {
  goToStep(Math.min(demoSteps.length - 1, currentStep + 1));
}

function goToStep(i) {
  currentStep = i;
  var st = demoSteps[i];
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = st.narration;
  if (label) label.textContent = (i + 1) + '/' + demoSteps.length + ' ' + st.title;
  var slider = document.getElementById('baseEquivalentsInput');
