  currentEq = st.state.baseEquivalents;
  var out = document.getElementById('baseEquivalentsVal');
  if (out) out.value = currentEq.toFixed(2);
  var cb = document.getElementById('rightPanelViewInput');
  netChargeView = st.state.rightPanelView === 'Net charge';
  if (cb) cb.checked = netChargeView;
  var lab = document.getElementById('rightPanelViewVal');
  if (lab) lab.textContent = netChargeView ? 'Net charge' : 'Species';
  selectedLandmark = activeRegion();
  if (chart) chart.update('none');
}

function roundRect(ctx, x, y, w, h, r, fill, stroke) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
  if (fill) ctx.fill();
  if (stroke) ctx.stroke();
}

function drawArrow(ctx, x1, y1, x2, y2, color, width, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  var len = 7;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - len * Math.cos(a - Math.PI / 7), y2 - len * Math.sin(a - Math.PI / 7));
  ctx.lineTo(x2 - len * Math.cos(a + Math.PI / 7), y2 - len * Math.sin(a + Math.PI / 7));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawTextHalo(ctx, text, x, y, color, font, align) {
  ctx.save();
  ctx.font = font;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.lineWidth = 4;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color || '#111';
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawSegmentedText(ctx, pieces, x, y, fs) {
  var cx = x;
  ctx.textBaseline = 'alphabetic';
  ctx.font = fs + 'px Arial';
  for (var i = 0; i < pieces.length; i++) {
    var p = pieces[i];
    if (p.sub || p.sup) {
      ctx.font = Math.max(7, fs * 0.68) + 'px Arial';
      ctx.fillStyle = p.color || '#111';
      ctx.fillText(p.text, cx, y + (p.sub ? fs * 0.22 : -fs * 0.45));
      cx += ctx.measureText(p.text).width;
      ctx.font = fs + 'px Arial';
    } else {
      ctx.fillStyle = p.color || '#111';
      ctx.fillText(p.text, cx, y);
      cx += ctx.measureText(p.text).width;
    }
  }
  return cx - x;
}

function drawAlanine(ctx, x, y, kind, s) {
  var fs = Math.max(8, 15 * s);
  var mag = '#ff0099', blue = '#008bd2', black = '#111';
  ctx.save();
  ctx.lineWidth = Math.max(0.8, 1.2 * s);
  ctx.strokeStyle = black;
  ctx.fillStyle = black;
  ctx.font = fs + 'px Arial';
  var protonatedN = kind !== 'deprot';
  var acid = kind === 'full';
  drawSegmentedText(ctx, [
    { text: 'H', color: protonatedN ? mag : blue },
    { text: protonatedN ? '3' : '2', color: protonatedN ? mag : blue, sub: true },
    { text: 'N', color: protonatedN ? mag : blue }
  ], x, y, fs);
  if (protonatedN) {
    ctx.font = Math.max(7, fs * 0.76) + 'px Arial';
    ctx.fillStyle = black;
    ctx.fillText('+', x + 30 * s, y - 12 * s);
  }
  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.fillText('CH', x + 45 * s, y);
  ctx.fillText('C', x + 82 * s, y);
  ctx.fillText('O', x + 106 * s, y);
  if (acid) {
    ctx.fillStyle = mag;
    ctx.fillText('H', x + 119 * s, y);
  } else {
    ctx.font = Math.max(8, fs * 0.82) + 'px Arial';
    ctx.fillStyle = black;
    ctx.fillText('−', x + 121 * s, y - 4 * s);
  }
  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.fillText('O', x + 82 * s, y - 36 * s);
  ctx.beginPath();
  ctx.moveTo(x + 86 * s, y - 8 * s);
  ctx.lineTo(x + 86 * s, y - 28 * s);
  ctx.moveTo(x + 93 * s, y - 8 * s);
  ctx.lineTo(x + 93 * s, y - 28 * s);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x + 56 * s, y + 5 * s);
  ctx.lineTo(x + 56 * s, y + 24 * s);
  ctx.stroke();
  drawSegmentedText(ctx, [{ text: 'CH', color: black }, { text: '3', sub: true, color: black }], x + 45 * s, y + 43 * s, fs);
  ctx.restore();
  return { x: x - 8 * s, y: y - 47 * s, w: 145 * s, h: 101 * s };
}

function drawBracket(ctx, x, y, w, h, s) {
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(0.8, 1.2 * s);
  var k = 12 * s;
  ctx.beginPath();
  ctx.moveTo(x + k, y); ctx.lineTo(x, y); ctx.lineTo(x, y + h); ctx.lineTo(x + k, y + h);
  ctx.moveTo(x + w - k, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - k, y + h);
