  ctx.restore();
}

function drawChargeCard(ctx, x, y, w, h, title, body, charge, active) {
  ctx.save();
  if (active) {
    ctx.fillStyle = 'rgba(255,0,153,0.10)';
    ctx.strokeStyle = '#ff0099';
  } else {
