  ctx.font = 'bold 22px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(charge, x + 35, y + h / 2);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#111';
  ctx.font = 'bold 13px Arial';
  ctx.fillText(title, x + 70, y + 22);
  ctx.font = '11px Arial';
  ctx.fillText(body, x + 70, y + 43);
  ctx.restore();
}

function drawFigure(chart) {
  var ctx = chart.ctx, W = chart.width, H = chart.height;
  ctx.clearRect(0, 0, W, H);
  hitRegions = [];

  var small = W < 760;
  var plotX0 = 54, plotY0 = 34;
  var plotH = Math.max(300, H - 84);
  var plotW = small ? Math.max(255, W * 0.45) : Math.min(W * 0.43, 470);
  if (plotX0 + plotW > W - 230) plotW = Math.max(240, W - 285 - plotX0);
  var rightX = plotX0 + plotW + 38;
  var rightW = Math.max(180, W - rightX - 10);
  var s = Math.min(1, rightW / 520, H / 610);
  if (small) s = Math.max(0.58, s);

  function px(eq) { return plotX0 + (eq / 2) * plotW; }
  function py(pH) { return plotY0 + plotH - (pH / 12) * plotH; }

  ctx.fillStyle = '#e3f5ff';
  ctx.fillRect(plotX0, plotY0, plotW, plotH);

  ctx.strokeStyle = 'rgba(0,0,0,0.42)';
  ctx.lineWidth = 1;
  ctx.font = '12px Arial';
  ctx.fillStyle = '#111';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (var yy = 0; yy <= 12; yy += 2) {
    var gy = py(yy);
    ctx.beginPath();
    ctx.moveTo(plotX0, gy);
    ctx.lineTo(plotX0 + plotW, gy);
    ctx.stroke();
    ctx.fillText(String(yy), plotX0 - 10, gy);
  }
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  for (var xx = 0; xx <= 2.001; xx += 0.5) {
    var gx = px(xx);
    ctx.beginPath();
    ctx.moveTo(gx, plotY0);
    ctx.lineTo(gx, plotY0 + plotH);
    ctx.stroke();
    ctx.fillText(xx.toFixed(1), gx, plotY0 + plotH + 18);
  }

  ctx.strokeStyle = '#111';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(plotX0, plotY0);
  ctx.lineTo(plotX0, plotY0 + plotH);
  ctx.lineTo(plotX0 + plotW, plotY0 + plotH);
  ctx.stroke();

  ctx.font = '22px Arial';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  ctx.fillText('pH', plotX0 - 55, plotY0 + plotH / 2);
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Equivalents of HO−', plotX0 + plotW / 2, plotY0 + plotH + 44);

  ctx.strokeStyle = '#ff0099';
  ctx.lineWidth = Math.max(2, Math.min(plotW, plotH) * 0.006);
  ctx.beginPath();
