function nbarFromPH(pH) {
  var ka1 = Math.pow(10, -PKA1), ka2 = Math.pow(10, -PKA2);
  var h = Math.pow(10, -pH);
  var d = h * h + ka1 * h + ka1 * ka2;
  return (ka1 * h + 2 * ka1 * ka2) / d;
}

function pHFromEq(eq) {
  if (eq <= 0) return 0;
  if (eq >= 2) return 11.6;
  var lo = -0.2, hi = 12.2;
  for (var i = 0; i < 70; i++) {
    var mid = (lo + hi) / 2;
    if (nbarFromPH(mid) < eq) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

function activeRegion() {
  if (currentEq < 0.25) return 'low';
  if (currentEq < 0.75) return 'pKa1';
  if (currentEq < 1.25) return 'pI';
  if (currentEq < 1.75) return 'pKa2';
  return 'high';
}

function update_baseEquivalents(v) {
  currentEq = Math.max(0, Math.min(2, v));
  selectedLandmark = activeRegion();
  var out = document.getElementById('baseEquivalentsVal');
  if (out) out.value = currentEq.toFixed(2);
  if (chart) chart.update('none');
}

function toggle_rightPanelView(on) {
  netChargeView = !!on;
  var lab = document.getElementById('rightPanelViewVal');
  if (lab) lab.textContent = netChargeView ? 'Net charge' : 'Species';
  if (chart) chart.update('none');
}

function prevStep() {
  goToStep(Math.max(0, currentStep - 1));
}

function nextStep() {
  goToStep(Math.min(demoSteps.length - 1, currentStep + 1));
}

function goToStep(i) {
  currentStep = i;
  var st = demoSteps[i];
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = st.narration;
  if (label) label.textContent = (i + 1) + '/' + demoSteps.length + ' ' + st.title;
  var slider = document.getElementById('baseEquivalentsInput');
