}

function roundRect(ctx, x, y, w, h, r, fill, stroke) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
  if (fill) ctx.fill();
  if (stroke) ctx.stroke();
}

function drawArrow(ctx, x1, y1, x2, y2, color, width, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  var len = 7;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - len * Math.cos(a - Math.PI / 7), y2 - len * Math.sin(a - Math.PI / 7));
  ctx.lineTo(x2 - len * Math.cos(a + Math.PI / 7), y2 - len * Math.sin(a + Math.PI / 7));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawTextHalo(ctx, text, x, y, color, font, align) {
  ctx.save();
  ctx.font = font;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.92)';
  ctx.lineWidth = 4;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color || '#111';
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawSegmentedText(ctx, pieces, x, y, fs) {
  var cx = x;
  ctx.textBaseline = 'alphabetic';
  ctx.font = fs + 'px Arial';
  for (var i = 0; i < pieces.length; i++) {
    var p = pieces[i];
    if (p.sub || p.sup) {
      ctx.font = Math.max(7, fs * 0.68) + 'px Arial';
      ctx.fillStyle = p.color || '#111';
      ctx.fillText(p.text, cx, y + (p.sub ? fs * 0.22 : -fs * 0.45));
      cx += ctx.measureText(p.text).width;
      ctx.font = fs + 'px Arial';
    } else {
      ctx.fillStyle = p.color || '#111';
      ctx.fillText(p.text, cx, y);
      cx += ctx.measureText(p.text).width;
    }
  }
  return cx - x;
}

function drawAlanine(ctx, x, y, kind, s) {
  var fs = Math.max(8, 15 * s);
  var mag = '#ff0099', blue = '#008bd2', black = '#111';
  ctx.save();
  ctx.lineWidth = Math.max(0.8, 1.2 * s);
  ctx.strokeStyle = black;
  ctx.fillStyle = black;
  ctx.font = fs + 'px Arial';
  var protonatedN = kind !== 'deprot';
  var acid = kind === 'full';
  drawSegmentedText(ctx, [
    { text: 'H', color: protonatedN ? mag : blue },
    { text: protonatedN ? '3' : '2', color: protonatedN ? mag : blue, sub: true },
    { text: 'N', color: protonatedN ? mag : blue }
  ], x, y, fs);
  if (protonatedN) {
    ctx.font = Math.max(7, fs * 0.76) + 'px Arial';
    ctx.fillStyle = black;
    ctx.fillText('+', x + 30 * s, y - 12 * s);
  }
  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.fillText('CH', x + 45 * s, y);
  ctx.fillText('C', x + 82 * s, y);
  ctx.fillText('O', x + 106 * s, y);
  if (acid) {
    ctx.fillStyle = mag;
    ctx.fillText('H', x + 119 * s, y);
  } else {
    ctx.font = Math.max(8, fs * 0.82) + 'px Arial';
    ctx.fillStyle = black;
    ctx.fillText('−', x + 121 * s, y - 4 * s);
  }
  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.fillText('O', x + 82 * s, y - 36 * s);
  ctx.beginPath();
  ctx.moveTo(x + 86 * s, y - 8 * s);
  ctx.lineTo(x + 86 * s, y - 28 * s);
  ctx.moveTo(x + 93 * s, y - 8 * s);
  ctx.lineTo(x + 93 * s, y - 28 * s);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x + 56 * s, y + 5 * s);
  ctx.lineTo(x + 56 * s, y + 24 * s);
  ctx.stroke();
  drawSegmentedText(ctx, [{ text: 'CH', color: black }, { text: '3', sub: true, color: black }], x + 45 * s, y + 43 * s, fs);
  ctx.restore();
  return { x: x - 8 * s, y: y - 47 * s, w: 145 * s, h: 101 * s };
}

function drawBracket(ctx, x, y, w, h, s) {
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(0.8, 1.2 * s);
  var k = 12 * s;
  ctx.beginPath();
  ctx.moveTo(x + k, y); ctx.lineTo(x, y); ctx.lineTo(x, y + h); ctx.lineTo(x + k, y + h);
  ctx.moveTo(x + w - k, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - k, y + h);
  ctx.stroke();
  ctx.restore();
}

function drawChargeCard(ctx, x, y, w, h, title, body, charge, active) {
  ctx.save();
  if (active) {
    ctx.fillStyle = 'rgba(255,0,153,0.10)';
    ctx.strokeStyle = '#ff0099';
  } else {
    ctx.fillStyle = 'rgba(255,255,255,0.72)';
    ctx.strokeStyle = 'rgba(0,0,0,0.25)';
  }
  ctx.lineWidth = active ? 2 : 1;
  roundRect(ctx, x, y, w, h, 10, true, true);
  ctx.fillStyle = charge === '+1' ? '#ff0099' : (charge === '−1' ? '#008bd2' : '#111');
  ctx.font = 'bold 22px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(charge, x + 35, y + h / 2);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#111';
  ctx.font = 'bold 13px Arial';
  ctx.fillText(title, x + 70, y + 22);
  ctx.font = '11px Arial';
  ctx.fillText(body, x + 70, y + 43);
  ctx.restore();
}

function drawFigure(chart) {
  var ctx = chart.ctx, W = chart.width, H = chart.height;
  ctx.clearRect(0, 0, W, H);
  hitRegions = [];

  var small = W < 760;
  var plotX0 = 54, plotY0 = 34;
  var plotH = Math.max(300, H - 84);
  var plotW = small ? Math.max(255, W * 0.45) : Math.min(W * 0.43, 470);
  if (plotX0 + plotW > W - 230) plotW = Math.max(240, W - 285 - plotX0);
  var rightX = plotX0 + plotW + 38;
  var rightW = Math.max(180, W - rightX - 10);
  var s = Math.min(1, rightW / 520, H / 610);
  if (small) s = Math.max(0.58, s);

  function px(eq) { return plotX0 + (eq / 2) * plotW; }
  function py(pH) { return plotY0 + plotH - (pH / 12) * plotH; }

  ctx.fillStyle = '#e3f5ff';
  ctx.fillRect(plotX0, plotY0, plotW, plotH);

  ctx.strokeStyle = 'rgba(0,0,0,0.42)';
  ctx.lineWidth = 1;
  ctx.font = '12px Arial';
  ctx.fillStyle = '#111';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (var yy = 0; yy <= 12; yy += 2) {
    var gy = py(yy);
    ctx.beginPath();
    ctx.moveTo(plotX0, gy);
    ctx.lineTo(plotX0 + plotW, gy);
    ctx.stroke();
    ctx.fillText(String(yy), plotX0 - 10, gy);
  }
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  for (var xx = 0; xx <= 2.001; xx += 0.5) {
    var gx = px(xx);
    ctx.beginPath();
    ctx.moveTo(gx, plotY0);
    ctx.lineTo(gx, plotY0 + plotH);
    ctx.stroke();
    ctx.fillText(xx.toFixed(1), gx, plotY0 + plotH + 18);
  }

  ctx.strokeStyle = '#111';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(plotX0, plotY0);
  ctx.lineTo(plotX0, plotY0 + plotH);
  ctx.lineTo(plotX0 + plotW, plotY0 + plotH);
  ctx.stroke();

  ctx.font = '22px Arial';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  ctx.fillText('pH', plotX0 - 55, plotY0 + plotH / 2);
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Equivalents of HO−', plotX0 + plotW / 2, plotY0 + plotH + 44);

  ctx.strokeStyle = '#ff0099';
  ctx.lineWidth = Math.max(2, Math.min(plotW, plotH) * 0.006);
  ctx.beginPath();
  for (var i = 0; i <= 400; i++) {
    var eq = 2 * i / 400;
    var ph = pHFromEq(eq);
    var cx = px(eq), cy = py(ph);
    if (i === 0) ctx.moveTo(cx, cy);
    else ctx.lineTo(cx, cy);
  }
  ctx.stroke();

  var landmarks = [
    { id: 'pKa1', eq: 0.5, ph: PKA1, label: 'pKa1 = 2.34', lx: px(0.06), ly: py(3.55), popup: 'At pKa1, the carboxyl group is half deprotonated. Fully protonated alanine and the zwitterion are present in equal amounts.' },
    { id: 'pI', eq: 1.0, ph: PI, label: 'Isoelectric\npoint = 6.01', lx: px(0.43), ly: py(6.9), popup: 'The isoelectric point is not a 50:50 mixture point. It is where the neutral zwitterion dominates, with +1 and −1 internal charges canceling to net zero.' },
    { id: 'pKa2', eq: 1.5, ph: PKA2, label: 'pKa2 = 9.69', lx: px(1.05), ly: py(11.65), popup: 'At pKa2, the ammonium group is half deprotonated. The zwitterion and the fully deprotonated anion are present in equal amounts.' }
  ];

  ctx.font = '16px Arial';
  landmarks.forEach(function (lm) {
    var x = px(lm.eq), y = py(lm.ph);
    if (selectedLandmark === lm.id) {
      ctx.save();
      ctx.strokeStyle = 'rgba(255,0,153,0.45)';
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.arc(x, y, 10, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
    ctx.strokeStyle = '#111';
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(x - 7, y - 7); ctx.lineTo(x + 7, y + 7);
    ctx.moveTo(x + 7, y - 7); ctx.lineTo(x - 7, y + 7);
    ctx.stroke();
    drawArrow(ctx, lm.lx + (lm.id === 'pI' ? 92 : 72), lm.ly - 4, x - 5, y - 2, '#111', 1, 0.95);
    if (lm.label.indexOf('\n') >= 0) {
      drawTextHalo(ctx, 'Isoelectric', lm.lx, lm.ly - 16, '#111', '15px Arial', 'left');
      drawTextHalo(ctx, 'point = 6.01', lm.lx, lm.ly + 2, '#111', '15px Arial', 'left');
    } else {
      drawTextHalo(ctx, lm.label, lm.lx, lm.ly, '#111', '16px Arial', 'left');
    }
    hitRegions.push({ type: 'landmark', id: lm.id, x: x - 14, y: y - 14, w: 28, h: 28, text: lm.label.replace('\n', ' '), popup: lm.popup, eq: lm.eq });
  });

  var mPh = pHFromEq(currentEq);
  var mx = px(currentEq), my = py(mPh);
  ctx.save();
  ctx.fillStyle = '#fff7a8';
  ctx.strokeStyle = '#111';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(mx, my, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.restore();
  var readX = Math.min(plotX0 + plotW - 58, mx + 12);
  var readY = Math.max(plotY0 + 20, my - 14);
  drawTextHalo(ctx, 'pH ' + mPh.toFixed(2), readX, readY, '#111', '13px Arial', 'left');

  var yTop = py(11.4), yPka2 = py(9.05), yPi = py(6.0), yPka1 = py(2.75), yLow = py(0.35);
  var anchors = {
    high: { x: rightX + 12 * s, y: yTop },
    pKa2: { x: rightX + 6 * s, y: yPka2 },
    pI: { x: rightX + 10 * s, y: yPi },
    pKa1: { x: rightX + 6 * s, y: yPka1 },
    low: { x: rightX + 10 * s, y: yLow }
  };

  var ar = activeRegion();
  drawArrow(ctx, px(0.02), py(0.05), anchors.low.x - 10, anchors.low.y, '#111', selectedLandmark === 'low' ? 1.7 : 1, 0.95);
  drawArrow(ctx, px(0.55), py(PKA1), anchors.pKa1.x - 10, anchors.pKa1.y, '#111', selectedLandmark === 'pKa1' ? 1.7 : 1, 0.95);
  drawArrow(ctx, px(1.02), py(PI), anchors.pI.x - 10, anchors.pI.y, '#111', selectedLandmark === 'pI' ? 1.7 : 1, 0.95);
  drawArrow(ctx, px(1.52), py(PKA2), anchors.pKa2.x - 10, anchors.pKa2.y, '#111', selectedLandmark === 'pKa2' ? 1.7 : 1, 0.95);
  drawArrow(ctx, px(2.0), py(11.55), anchors.high.x - 10, anchors.high.y, '#111', selectedLandmark === 'high' ? 1.7 : 1, 0.95);

  if (netChargeView) {
    var cw = Math.min(330, rightW - 16), ch = 55;
    drawChargeCard(ctx, rightX + 8, yTop - 34, cw, ch, 'Fully deprotonated', 'H2NCH(CH3)COO−', '−1', ar === 'high');
    drawChargeCard(ctx, rightX + 8, yPka2 - 34, cw, ch, 'pKa2 mixture', '50:50 net 0 and −1 forms', '½', ar === 'pKa2');
    drawChargeCard(ctx, rightX + 8, yPi - 34, cw, ch, 'Isoelectric zwitterion', '+ and − internal charges cancel', '0', ar === 'pI');
    drawChargeCard(ctx, rightX + 8, yPka1 - 34, cw, ch, 'pKa1 mixture', '50:50 net +1 and 0 forms', '½', ar === 'pKa1');
    drawChargeCard(ctx, rightX + 8, yLow - 34, cw, ch, 'Fully protonated', 'H3N+CH(CH3)COOH', '+1', ar === 'low');
  } else {
    var box;
    if (ar === 'high') { ctx.fillStyle = 'rgba(0,139,210,0.10)'; ctx.strokeStyle = '#008bd2'; ctx.lineWidth = 2; roundRect(ctx, rightX - 2, yTop - 63 * s, 170 * s, 118 * s, 8, true, true); }
    box = drawAlanine(ctx, rightX + 14 * s, yTop, 'deprot', s);
    hitRegions.push({ type: 'species', x: box.x, y: box.y, w: box.w, h: box.h, text: 'Fully deprotonated alanine: H2NCH(CH3)COO−, net −1.' });

    if (ar === 'pKa2') { ctx.fillStyle = 'rgba(255,0,153,0.08)'; ctx.strokeStyle = '#ff0099'; ctx.lineWidth = 2; roundRect(ctx, rightX - 2, yPka2 - 68 * s, 360 * s, 128 * s, 8, true, true); }
    drawBracket(ctx, rightX, yPka2 - 70 * s, 370 * s, 130 * s, s);
    drawAlanine(ctx, rightX + 18 * s, yPka2, 'zwitter', s);
    ctx.fillStyle = '#111'; ctx.font = Math.max(11, 19 * s) + 'px Arial'; ctx.fillText('+', rightX + 168 * s, yPka2 - 2 * s);
    drawAlanine(ctx, rightX + 205 * s, yPka2, 'deprot', s);
    hitRegions.push({ type: 'species', x: rightX, y: yPka2 - 70 * s, w: 370 * s, h: 130 * s, text: 'pKa2: 50:50 zwitterion and deprotonated alanine.' });

    if (ar === 'pI') { ctx.fillStyle = 'rgba(255,0,153,0.10)'; ctx.strokeStyle = '#ff0099'; ctx.lineWidth = 2; roundRect(ctx, rightX - 2, yPi - 63 * s, 170 * s, 118 * s, 8, true, true); }
    box = drawAlanine(ctx, rightX + 14 * s, yPi, 'zwitter', s);
    hitRegions.push({ type: 'species', x: box.x, y: box.y, w: box.w, h: box.h, text: 'Zwitterionic alanine: internal + and − charges, net 0.' });

    if (ar === 'pKa1') { ctx.fillStyle = 'rgba(255,0,153,0.08)'; ctx.strokeStyle = '#ff0099'; ctx.lineWidth = 2; roundRect(ctx, rightX - 2, yPka1 - 68 * s, 360 * s, 128 * s, 8, true, true); }
    drawBracket(ctx, rightX, yPka1 - 70 * s, 370 * s, 130 * s, s);
    drawAlanine(ctx, rightX + 18 * s, yPka1, 'full', s);
    ctx.fillStyle = '#111'; ctx.font = Math.max(11, 19 * s) + 'px Arial'; ctx.fillText('+', rightX + 168 * s, yPka1 - 2 * s);
    drawAlanine(ctx, rightX + 205 * s, yPka1, 'zwitter', s);
    hitRegions.push({ type: 'species', x: rightX, y: yPka1 - 70 * s, w: 370 * s, h: 130 * s, text: 'pKa1: 50:50 fully protonated alanine and zwitterion.' });

    if (ar === 'low') { ctx.fillStyle = 'rgba(255,0,153,0.10)'; ctx.strokeStyle = '#ff0099'; ctx.lineWidth = 2; roundRect(ctx, rightX - 2, yLow - 63 * s, 170 * s, 118 * s, 8, true, true); }
    box = drawAlanine(ctx, rightX + 14 * s, yLow, 'full', s);
    hitRegions.push({ type: 'species', x: box.x, y: box.y, w: box.w, h: box.h, text: 'Fully protonated alanine: H3N+ and COOH, net +1.' });
  }
}

