  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = st.narration;
  if (label) label.textContent = (i + 1) + '/' + demoSteps.length + ' ' + st.title;
  currentEq = st.state.baseEquivalents;
  selectedLandmark = quietInitial ? null : activeRegion();
  showInteractiveMarker = !quietInitial;
  showLinkedHighlight = !quietInitial;
  var slider = document.getElementById('baseEquivalentsInput');
  if (slider) slider.value = currentEq;
  var out = document.getElementById('baseEquivalentsVal');
  if (out) out.value = currentEq.toFixed(2);
  var cb = document.getElementById('rightPanelViewInput');
  netChargeView = st.state.rightPanelView === 'Net charge';
  if (cb) cb.checked = netChargeView;
  var lab = document.getElementById('rightPanelViewVal');
  if (lab) lab.textContent = netChargeView ? 'Net charge' : 'Species';
  if (chart) chart.update('none');
}

function roundRect(ctx, x, y, w, h, r, fill, stroke) {
  var rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
  if (fill) ctx.fill();
  if (stroke) ctx.stroke();
}

function drawArrow(ctx, x1, y1, x2, y2, color, width, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  var len = Math.max(4, Math.min(8, width * 5.5));
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - len * Math.cos(a - Math.PI / 7), y2 - len * Math.sin(a - Math.PI / 7));
  ctx.lineTo(x2 - len * Math.cos(a + Math.PI / 7), y2 - len * Math.sin(a + Math.PI / 7));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawTextHalo(ctx, text, x, y, color, font, align) {
  ctx.save();
  ctx.font = font;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.94)';
  ctx.lineWidth = 4;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color || '#111';
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawSegmentedText(ctx, pieces, x, y, fs) {
  var cx = x;
  ctx.textBaseline = 'alphabetic';
  ctx.font = fs + 'px Arial';
  for (var i = 0; i < pieces.length; i++) {
    var p = pieces[i];
    if (p.sub || p.sup) {
      ctx.font = Math.max(7, fs * 0.68) + 'px Arial';
      ctx.fillStyle = p.color || '#111';
      ctx.fillText(p.text, cx, y + (p.sub ? fs * 0.22 : -fs * 0.48));
      cx += ctx.measureText(p.text).width;
      ctx.font = fs + 'px Arial';
    } else {
      ctx.fillStyle = p.color || '#111';
      ctx.fillText(p.text, cx, y);
      cx += ctx.measureText(p.text).width;
    }
  }
  return cx - x;
}

function drawAlanine(ctx, x, y, kind, s) {
  var fs = Math.max(10, 18 * s);
  var mag = '#ff0099', blue = '#008bd2', black = '#111';
  var protonatedN = kind !== 'deprot';
  var acid = kind === 'full';
  ctx.save();
  ctx.lineWidth = Math.max(0.9, 1.25 * s);
  ctx.strokeStyle = black;
  ctx.fillStyle = black;
  ctx.font = fs + 'px Arial';
  drawSegmentedText(ctx, [
    { text: 'H', color: protonatedN ? mag : blue },
    { text: protonatedN ? '3' : '2', color: protonatedN ? mag : blue, sub: true },
    { text: 'N', color: protonatedN ? mag : blue }
  ], x, y, fs);
  if (protonatedN) {
    ctx.font = Math.max(8, fs * 0.74) + 'px Arial';
    ctx.fillStyle = black;
    ctx.fillText('+', x + 32 * s, y - 13 * s);
  }
  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.fillText('CH', x + 45 * s, y);
  ctx.fillText('C', x + 82 * s, y);
  ctx.fillText('O', x + 107 * s, y);
  if (acid) {
    ctx.fillStyle = mag;
    ctx.fillText('H', x + 121 * s, y);
  } else {
    ctx.font = Math.max(8, fs * 0.80) + 'px Arial';
    ctx.fillStyle = black;
    ctx.fillText('−', x + 122 * s, y - 4 * s);
  }
  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.fillText('O', x + 82 * s, y - 38 * s);
  ctx.beginPath();
  ctx.moveTo(x + 87 * s, y - 9 * s);
  ctx.lineTo(x + 87 * s, y - 31 * s);
  ctx.moveTo(x + 94 * s, y - 9 * s);
  ctx.lineTo(x + 94 * s, y - 31 * s);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x + 56 * s, y + 6 * s);
  ctx.lineTo(x + 56 * s, y + 28 * s);
  ctx.stroke();
  drawSegmentedText(ctx, [{ text: 'CH', color: black }, { text: '3', sub: true, color: black }], x + 45 * s, y + 49 * s, fs);
  ctx.restore();
  return { x: x - 8 * s, y: y - 52 * s, w: 150 * s, h: 112 * s };
}

function drawBracket(ctx, x, y, w, h, s) {
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(0.8, 1.15 * s);
  var k = 10 * s;
  ctx.beginPath();
  ctx.moveTo(x + k, y); ctx.lineTo(x, y); ctx.lineTo(x, y + h); ctx.lineTo(x + k, y + h);
  ctx.moveTo(x + w - k, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - k, y + h);
  ctx.stroke();
  ctx.restore();
}

function drawChargeCard(ctx, x, y, w, h, title, body, charge, active, scale) {
  ctx.save();
  ctx.fillStyle = active ? 'rgba(255,0,153,0.08)' : 'rgba(255,255,255,0.74)';
  ctx.strokeStyle = active ? '#ff0099' : 'rgba(0,0,0,0.24)';
  ctx.lineWidth = active ? 1.7 : 1;
  roundRect(ctx, x, y, w, h, 9 * scale, true, true);
  ctx.fillStyle = charge === '+1' ? '#ff0099' : (charge === '−1' ? '#008bd2' : '#111');
  ctx.font = 'bold ' + Math.max(15, 22 * scale) + 'px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(charge, x + 34 * scale, y + h / 2);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#111';
  ctx.textBaseline = 'alphabetic';
  ctx.font = 'bold ' + Math.max(10, 13 * scale) + 'px Arial';
  ctx.fillText(title, x + 68 * scale, y + 22 * scale);
  ctx.font = Math.max(9, 11 * scale) + 'px Arial';
  ctx.fillText(body, x + 68 * scale, y + 43 * scale);
  ctx.restore();
}

function drawSpeciesGroupHighlight(ctx, x, y, w, h, color) {
  ctx.save();
  ctx.fillStyle = color === 'blue' ? 'rgba(0,139,210,0.075)' : 'rgba(255,0,153,0.065)';
  ctx.strokeStyle = color === 'blue' ? 'rgba(0,139,210,0.95)' : 'rgba(255,0,153,0.9)';
  ctx.lineWidth = 1.6;
  roundRect(ctx, x, y, w, h, 7, true, true);
  ctx.restore();
}

function drawFigure(chartInstance) {
  var ctx = chartInstance.ctx, W = chartInstance.width, H = chartInstance.height;
  ctx.clearRect(0, 0, W, H);
  hitRegions = [];

  var plotX0 = Math.max(48, W * 0.055);
  var plotY0 = Math.max(26, H * 0.045);
  var bottomPad = Math.max(76, H * 0.13);
  var plotH = Math.max(230, H - plotY0 - bottomPad);
  var plotW = Math.min(W * 0.43, 468);
  if (W < 720) plotW = Math.min(W * 0.45, 330);
  if (plotX0 + plotW > W - 220) plotW = Math.max(230, W - 250 - plotX0);
  var rightX = plotX0 + plotW + Math.max(30, W * 0.035);
  var rightW = Math.max(175, W - rightX - 8);
  var s = Math.min(1.08, rightW / 365, plotH / 505);
  if (W < 720) s = Math.min(0.82, Math.max(0.60, rightW / 360, plotH / 560));

  function px(eq) { return plotX0 + (eq / 2) * plotW; }
  function py(pH) { return plotY0 + plotH - (pH / 12) * plotH; }

  ctx.fillStyle = '#dff3ff';
  ctx.fillRect(plotX0, plotY0, plotW, plotH);

  ctx.strokeStyle = 'rgba(0,0,0,0.42)';
  ctx.lineWidth = 1;
  ctx.font = Math.max(10, Math.min(13, plotH * 0.032)) + 'px Arial';
  ctx.fillStyle = '#111';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (var yy = 0; yy <= 12; yy += 2) {
    var gy = py(yy);
    ctx.beginPath();
    ctx.moveTo(plotX0, gy);
    ctx.lineTo(plotX0 + plotW, gy);
    ctx.stroke();
    ctx.fillText(String(yy), plotX0 - 10, gy);
  }
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  for (var xx = 0; xx <= 2.001; xx += 0.5) {
    var gx = px(xx);
    ctx.beginPath();
    ctx.moveTo(gx, plotY0);
    ctx.lineTo(gx, plotY0 + plotH);
    ctx.stroke();
    ctx.fillText(xx.toFixed(1), gx, plotY0 + plotH + 15);
  }

  ctx.strokeStyle = '#111';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(plotX0, plotY0);
  ctx.lineTo(plotX0, plotY0 + plotH);
  ctx.lineTo(plotX0 + plotW, plotY0 + plotH);
  ctx.stroke();

  ctx.font = Math.max(16, Math.min(22, plotH * 0.055)) + 'px Arial';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#111';
  ctx.fillText('pH', plotX0 - 55, plotY0 + plotH / 2);
  ctx.font = Math.max(15, Math.min(19, plotW * 0.044)) + 'px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Equivalents of HO−', plotX0 + plotW / 2, plotY0 + plotH + 41);

  ctx.strokeStyle = '#ff0099';
  ctx.lineWidth = Math.max(1.8, Math.min(plotW, plotH) * 0.006);
  ctx.beginPath();
  for (var i = 0; i <= 460; i++) {
    var eq = 2 * i / 460;
    var ph = pHFromEq(eq);
    var cx = px(eq), cy = py(ph);
    if (i === 0) ctx.moveTo(cx, cy);
    else ctx.lineTo(cx, cy);
  }
  ctx.stroke();

  var landmarks = [
    { id: 'pKa1', eq: 0.5, ph: PKA1, label: 'pKₐ1 = 2.34', lx: px(0.05), ly: py(3.15), popup: 'At pKa1, the carboxyl group is half deprotonated. Fully protonated alanine and the zwitterion are present in equal amounts.' },
    { id: 'pI', eq: 1.0, ph: PI, label: 'Isoelectric\npoint = 6.01', lx: px(0.43), ly: py(6.78), popup: 'The isoelectric point is not a 50:50 mixture point. It is where the neutral zwitterion dominates, with +1 and −1 internal charges canceling to net zero.' },
    { id: 'pKa2', eq: 1.5, ph: PKA2, label: 'pKₐ2 = 9.69', lx: px(1.06), ly: py(10.95), popup: 'At pKa2, the ammonium group is half deprotonated. The zwitterion and the fully deprotonated anion are present in equal amounts.' }
  ];

  var labelFont = Math.max(12, Math.min(16, plotW * 0.038));
  landmarks.forEach(function (lm) {
    var x = px(lm.eq), y = py(lm.ph);
    if (showLinkedHighlight && selectedLandmark === lm.id) {
      ctx.save();
      ctx.strokeStyle = 'rgba(255,0,153,0.34)';
      ctx.lineWidth = Math.max(5, plotW * 0.016);
      ctx.beginPath();
      ctx.arc(x, y, Math.max(7, plotW * 0.022), 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
    ctx.strokeStyle = '#111';
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    ctx.moveTo(x - 6, y - 6); ctx.lineTo(x + 6, y + 6);
    ctx.moveTo(x + 6, y - 6); ctx.lineTo(x - 6, y + 6);
    ctx.stroke();

    if (lm.id === 'pKa1') {
      drawArrow(ctx, lm.lx + 88, lm.ly - 9, x - 5, y - 2, '#111', 1, 0.95);
    } else if (lm.id === 'pI') {
      drawArrow(ctx, lm.lx + 82, lm.ly - 3, x - 5, y - 1, '#111', 1, 0.95);
    } else {
      drawArrow(ctx, lm.lx + 62, lm.ly + 4, x - 5, y - 1, '#111', 1, 0.95);
    }

    if (lm.label.indexOf('\n') >= 0) {
      drawTextHalo(ctx, 'Isoelectric', lm.lx, lm.ly - labelFont * 0.75, '#111', labelFont + 'px Arial', 'left');
      drawTextHalo(ctx, 'point = 6.01', lm.lx, lm.ly + labelFont * 0.48, '#111', labelFont + 'px Arial', 'left');
    } else {
      drawTextHalo(ctx, lm.label, lm.lx, lm.ly, '#111', labelFont + 'px Arial', 'left');
    }
    hitRegions.push({ type: 'landmark', id: lm.id, x: x - 14, y: y - 14, w: 28, h: 28, text: lm.label.replace('\n', ' '), popup: lm.popup, eq: lm.eq });
  });

  if (showInteractiveMarker) {
    var mPh = pHFromEq(currentEq);
    var mx = px(currentEq), my = py(mPh);
    ctx.save();
    ctx.fillStyle = 'rgba(255,247,168,0.82)';
    ctx.strokeStyle = 'rgba(0,0,0,0.70)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(mx, my, Math.max(4.5, Math.min(6, plotW * 0.014)), 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    var readX = Math.min(plotX0 + plotW - 55, mx + 12);
    var readY = Math.max(plotY0 + 18, my - 13);
    drawTextHalo(ctx, 'pH ' + mPh.toFixed(2), readX, readY, '#111', Math.max(10, Math.min(13, plotW * 0.032)) + 'px Arial', 'left');
  }

  var yTop = py(11.55), yPka2 = py(9.45), yPi = py(6.0), yPka1 = py(2.85), yLow = py(0.35);
  var anchors = {
    high: { x: rightX + 8 * s, y: yTop },
    pKa2: { x: rightX + 4 * s, y: yPka2 },
    pI: { x: rightX + 8 * s, y: yPi },
    pKa1: { x: rightX + 4 * s, y: yPka1 },
    low: { x: rightX + 8 * s, y: yLow }
  };

  var ar = activeRegion();
  var activeLineW = showLinkedHighlight ? 1.45 : 1;
  drawArrow(ctx, px(0.02), py(0.05), anchors.low.x - 9, anchors.low.y, '#111', (ar === 'low' ? activeLineW : 1), 0.95);
  drawArrow(ctx, px(0.55), py(PKA1), anchors.pKa1.x - 9, anchors.pKa1.y, '#111', (ar === 'pKa1' ? activeLineW : 1), 0.95);
  drawArrow(ctx, px(1.02), py(PI), anchors.pI.x - 9, anchors.pI.y, '#111', (ar === 'pI' ? activeLineW : 1), 0.95);
  drawArrow(ctx, px(1.52), py(PKA2), anchors.pKa2.x - 9, anchors.pKa2.y, '#111', (ar === 'pKa2' ? activeLineW : 1), 0.95);
  drawArrow(ctx, px(2.0), py(11.55), anchors.high.x - 9, anchors.high.y, '#111', (ar === 'high' ? activeLineW : 1), 0.95);

  if (netChargeView) {
    var cw = Math.min(340, rightW - 12), ch = Math.max(48, 56 * s);
    drawChargeCard(ctx, rightX + 6, yTop - ch / 2, cw, ch, 'Fully deprotonated', 'H2NCH(CH3)COO−', '−1', showLinkedHighlight && ar === 'high', s);
    drawChargeCard(ctx, rightX + 6, yPka2 - ch / 2, cw, ch, 'pKa2 mixture', '50:50 net 0 and −1 forms', '½', showLinkedHighlight && ar === 'pKa2', s);
    drawChargeCard(ctx, rightX + 6, yPi - ch / 2, cw, ch, 'Isoelectric zwitterion', '+ and − internal charges cancel', '0', showLinkedHighlight && ar === 'pI', s);
    drawChargeCard(ctx, rightX + 6, yPka1 - ch / 2, cw, ch, 'pKa1 mixture', '50:50 net +1 and 0 forms', '½', showLinkedHighlight && ar === 'pKa1', s);
    drawChargeCard(ctx, rightX + 6, yLow - ch / 2, cw, ch, 'Fully protonated', 'H3N+CH(CH3)COOH', '+1', showLinkedHighlight && ar === 'low', s);
  } else {
    var box, bwSingle = 156 * s, bhSingle = 124 * s, pairW = 360 * s, pairH = 130 * s;

    if (showLinkedHighlight && ar === 'high') drawSpeciesGroupHighlight(ctx, rightX - 4, yTop - 64 * s, bwSingle + 18 * s, bhSingle, 'blue');
    drawBracket(ctx, rightX, yTop - 70 * s, 154 * s, 128 * s, s);
    box = drawAlanine(ctx, rightX + 18 * s, yTop, 'deprot', s);
    hitRegions.push({ type: 'species', x: rightX, y: yTop - 70 * s, w: 154 * s, h: 128 * s, text: 'Fully deprotonated alanine: H2NCH(CH3)COO−, net −1.' });

    if (showLinkedHighlight && ar === 'pKa2') drawSpeciesGroupHighlight(ctx, rightX - 4, yPka2 - 70 * s, pairW + 10 * s, pairH, 'magenta');
    drawBracket(ctx, rightX, yPka2 - 70 * s, pairW, pairH, s);
    drawAlanine(ctx, rightX + 18 * s, yPka2, 'zwitter', s);
    ctx.fillStyle = '#111';
    ctx.font = Math.max(12, 20 * s) + 'px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('+', rightX + 166 * s, yPka2 - 2 * s);
    drawAlanine(ctx, rightX + 205 * s, yPka2, 'deprot', s);
    hitRegions.push({ type: 'species', x: rightX, y: yPka2 - 70 * s, w: pairW, h: pairH, text: 'pKa2: a 50:50 mixture of zwitterionic alanine and fully deprotonated alanine.' });

    if (showLinkedHighlight && ar === 'pI') drawSpeciesGroupHighlight(ctx, rightX - 4, yPi - 64 * s, bwSingle + 18 * s, bhSingle, 'magenta');
    drawBracket(ctx, rightX, yPi - 70 * s, 154 * s, 128 * s, s);
    box = drawAlanine(ctx, rightX + 18 * s, yPi, 'zwitter', s);
    hitRegions.push({ type: 'species', x: rightX, y: yPi - 70 * s, w: 154 * s, h: 128 * s, text: 'Zwitterionic alanine: internal + and − charges cancel, giving net charge 0.' });

    if (showLinkedHighlight && ar === 'pKa1') drawSpeciesGroupHighlight(ctx, rightX - 4, yPka1 - 70 * s, pairW + 10 * s, pairH, 'magenta');
    drawBracket(ctx, rightX, yPka1 - 70 * s, pairW, pairH, s);
    drawAlanine(ctx, rightX + 18 * s, yPka1, 'full', s);
    ctx.fillStyle = '#111';
    ctx.font = Math.max(12, 20 * s) + 'px Arial';
    ctx.fillText('+', rightX + 166 * s, yPka1 - 2 * s);
    drawAlanine(ctx, rightX + 205 * s, yPka1, 'zwitter', s);
    hitRegions.push({ type: 'species', x: rightX, y: yPka1 - 70 * s, w: pairW, h: pairH, text: 'pKa1: a 50:50 mixture of fully protonated alanine and zwitterionic alanine.' });

    if (showLinkedHighlight && ar === 'low') drawSpeciesGroupHighlight(ctx, rightX - 4, yLow - 64 * s, bwSingle + 18 * s, bhSingle, 'magenta');
    drawBracket(ctx, rightX, yLow - 70 * s, 154 * s, 128 * s, s);
    box = drawAlanine(ctx, rightX + 18 * s, yLow, 'full', s);
    hitRegions.push({ type: 'species', x: rightX, y: yLow - 70 * s, w: 154 * s, h: 128 * s, text: 'Fully protonated alanine: H3N+ and COOH, net +1.' });
  }
}

