function nbarFromPH(pH) {
  var ka1 = Math.pow(10, -PKA1), ka2 = Math.pow(10, -PKA2);
  var h = Math.pow(10, -pH);
  var d = h * h + ka1 * h + ka1 * ka2;
  return (ka1 * h + 2 * ka1 * ka2) / d;
}

function pHFromEq(eq) {
  if (eq <= 0) return 0.02;
  if (eq >= 2) return 11.58;
  var lo = -0.2, hi = 12.2;
  for (var i = 0; i < 76; i++) {
    var mid = (lo + hi) / 2;
    if (nbarFromPH(mid) < eq) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

function activeRegion() {
  if (currentEq < 0.25) return 'low';
  if (currentEq < 0.75) return 'pKa1';
  if (currentEq < 1.25) return 'pI';
  if (currentEq < 1.75) return 'pKa2';
