function roundRect(ctx, x, y, w, h, r, fill, stroke) {
  var rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
  if (fill) ctx.fill();
  if (stroke) ctx.stroke();
}

function drawLeader(ctx, x1, y1, x2, y2, active) {
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.fillStyle = '#111';
  ctx.globalAlpha = active ? 0.96 : 0.88;
  ctx.lineWidth = active ? 1.15 : 0.85;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  var len = active ? 5.0 : 4.2;
  var wid = active ? 2.7 : 2.2;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - len * Math.cos(a) + wid * Math.sin(a), y2 - len * Math.sin(a) - wid * Math.cos(a));
  ctx.lineTo(x2 - len * Math.cos(a) - wid * Math.sin(a), y2 - len * Math.sin(a) + wid * Math.cos(a));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawAnnotationArrow(ctx, x1, y1, x2, y2) {
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.fillStyle = '#111';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  var cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
  ctx.quadraticCurveTo(cx, cy, x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  var len = 5;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - len * Math.cos(a - Math.PI / 7), y2 - len * Math.sin(a - Math.PI / 7));
  ctx.lineTo(x2 - len * Math.cos(a + Math.PI / 7), y2 - len * Math.sin(a + Math.PI / 7));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawTextHalo(ctx, text, x, y, color, font, align, baseline) {
  ctx.save();
  ctx.font = font;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = baseline || 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.96)';
  ctx.lineWidth = 4;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color || '#111';
  ctx.fillText(text, x, y);
  ctx.restore();
}

function richTextWidth(ctx, pieces, fs) {
  var w = 0;
  for (var i = 0; i < pieces.length; i++) {
    var p = pieces[i];
    ctx.font = (p.sub || p.sup ? Math.max(6, fs * 0.68) : fs) + 'px Arial';
    w += ctx.measureText(p.text).width;
  }
  return w;
}

function drawRichText(ctx, pieces, x, y, fs, align) {
  ctx.save();
  var total = richTextWidth(ctx, pieces, fs);
  var cx = align === 'center' ? x - total / 2 : x;
  ctx.textBaseline = 'alphabetic';
  for (var i = 0; i < pieces.length; i++) {
    var p = pieces[i];
    var small = p.sub || p.sup;
    ctx.font = (small ? Math.max(6, fs * 0.68) : fs) + 'px Arial';
    ctx.fillStyle = p.color || '#111';
    ctx.fillText(p.text, cx, y + (p.sub ? fs * 0.24 : (p.sup ? -fs * 0.50 : 0)));
    cx += ctx.measureText(p.text).width;
  }
  ctx.restore();
  return total;
}

function drawBond(ctx, x1, y1, x2, y2, lw) {
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
