}

function drawAlanine(ctx, x, y, kind, s) {
  var mag = '#ff0099', blue = '#008bd2', black = '#111';
  var protonatedN = kind !== 'deprot';
  var acid = kind === 'full';
  var fs = 21.5 * s;
  var smallStroke = Math.max(0.75, 1.15 * s);
  var xN = x, xCH = x + 58 * s, xC = x + 103 * s, xOR = x + 133 * s, xOtop = x + 103 * s;
  var yBase = y, yTop = y - 44 * s, yBot = y + 45 * s;
  ctx.save();
  ctx.strokeStyle = black;
  ctx.lineWidth = smallStroke;
  ctx.lineCap = 'round';

  drawBond(ctx, x + 41 * s, yBase - 5 * s, xCH - 5 * s, yBase - 5 * s, smallStroke);
  drawBond(ctx, xCH + 29 * s, yBase - 5 * s, xC - 4 * s, yBase - 5 * s, smallStroke);
  drawBond(ctx, xC + 10 * s, yBase - 5 * s, xOR - 6 * s, yBase - 5 * s, smallStroke);
  drawBond(ctx, xCH + 10 * s, yBase + 6 * s, xCH + 10 * s, yBot - 18 * s, smallStroke);
  drawBond(ctx, xC - 3 * s, yBase - 17 * s, xOtop - 3 * s, yTop + 14 * s, smallStroke);
  drawBond(ctx, xC + 4 * s, yBase - 17 * s, xOtop + 4 * s, yTop + 14 * s, smallStroke);

  drawRichText(ctx, [
    { text: 'H', color: protonatedN ? mag : blue },
    { text: protonatedN ? '3' : '2', color: protonatedN ? mag : blue, sub: true },
    { text: 'N', color: protonatedN ? mag : blue },
    protonatedN ? { text: '+', color: black, sup: true } : { text: '', color: black }
  ], xN, yBase, fs, 'left');

  ctx.font = fs + 'px Arial';
  ctx.fillStyle = black;
  ctx.textBaseline = 'alphabetic';
  ctx.fillText('CH', xCH, yBase);
  ctx.fillText('C', xC, yBase);
  ctx.fillText('O', xOtop - 7 * s, yTop);
  ctx.fillText('O', xOR, yBase);
  if (acid) {
    ctx.fillStyle = mag;
    ctx.fillText('H', xOR + 18 * s, yBase);
  } else {
    drawRichText(ctx, [{ text: '−', color: black, sup: true }], xOR + 20 * s, yBase, fs, 'left');
  }
  drawRichText(ctx, [{ text: 'CH', color: black }, { text: '3', color: black, sub: true }], xCH - 1 * s, yBot, fs, 'left');

  ctx.restore();
  return { x: x - 4 * s, y: yTop - 18 * s, w: 163 * s, h: 82 * s + (yBot - yTop) };
}

function drawBracket(ctx, x, y, w, h, s) {
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(0.75, 1.05 * s);
  var k = 8 * s;
  ctx.beginPath();
  ctx.moveTo(x + k, y); ctx.lineTo(x, y); ctx.lineTo(x, y + h); ctx.lineTo(x + k, y + h);
  ctx.moveTo(x + w - k, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - k, y + h);
  ctx.stroke();
  ctx.restore();
}

function drawSpeciesGroupHighlight(ctx, x, y, w, h, color, s) {
  ctx.save();
  ctx.fillStyle = color === 'blue' ? 'rgba(0,139,210,0.075)' : 'rgba(255,0,153,0.065)';
  ctx.strokeStyle = color === 'blue' ? 'rgba(0,139,210,0.92)' : 'rgba(255,0,153,0.88)';
  ctx.lineWidth = Math.max(1, 1.4 * s);
  roundRect(ctx, x, y, w, h, 7 * s, true, true);
  ctx.restore();
}

function drawChargeCard(ctx, x, y, w, h, title, body, charge, active, scale) {
  ctx.save();
  ctx.fillStyle = active ? 'rgba(255,0,153,0.08)' : 'rgba(255,255,255,0.78)';
  ctx.strokeStyle = active ? '#ff0099' : 'rgba(0,0,0,0.25)';
  ctx.lineWidth = active ? 1.6 : 1;
  roundRect(ctx, x, y, w, h, 9 * scale, true, true);
  ctx.fillStyle = charge === '+1' ? '#ff0099' : (charge === '−1' ? '#008bd2' : '#111');
  ctx.font = 'bold ' + (22 * scale) + 'px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(charge, x + 34 * scale, y + h / 2);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#111';
  ctx.textBaseline = 'alphabetic';
  ctx.font = 'bold ' + (13 * scale) + 'px Arial';
  ctx.fillText(title, x + 68 * scale, y + 22 * scale);
  ctx.font = (11 * scale) + 'px Arial';
  ctx.fillText(body, x + 68 * scale, y + 43 * scale);
  ctx.restore();
}

function drawFigure(chartInstance) {
  var ctx = chartInstance.ctx, W = chartInstance.width, H = chartInstance.height;
  ctx.clearRect(0, 0, W, H);
  hitRegions = [];

  var plotX0 = W * 0.055;
  var plotY0 = H * 0.055;
  var bottomPad = H * 0.125;
  var plotH = H - plotY0 - bottomPad;
  var plotW = Math.min(W * 0.405, 475);
  if (W < 760) plotW = W * 0.385;
  if (plotW < W * 0.33) plotW = W * 0.33;
  var gap = Math.max(14, W * 0.022);
  var rightX = plotX0 + plotW + gap;
  var rightW = Math.max(120, W - rightX - 4);

  function px(eq) { return plotX0 + (eq / 2) * plotW; }
  function py(pH) { return plotY0 + plotH - (pH / 12) * plotH; }

  var pairOffset = rightW > 445 ? rightW * 0.275 : rightW * 0.045;
  var singleOffset = rightW > 445 ? rightW * 0.075 : rightW * 0.03;
  var pairX = rightX + pairOffset;
  var singleX = rightX + singleOffset;
  var s = Math.min(1.04, plotH / 520, rightW / 430, (W - pairX - 8) / 352);
  s = Math.max(0.56, s);

  ctx.fillStyle = '#dff3ff';
  ctx.fillRect(plotX0, plotY0, plotW, plotH);

  ctx.strokeStyle = 'rgba(0,0,0,0.42)';
  ctx.lineWidth = 1;
  var tickFs = Math.max(9, Math.min(13, Math.min(plotW, plotH) * 0.035));
  ctx.font = tickFs + 'px Arial';
  ctx.fillStyle = '#111';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (var yy = 0; yy <= 12; yy += 2) {
    var gy = py(yy);
    ctx.beginPath();
    ctx.moveTo(plotX0, gy);
    ctx.lineTo(plotX0 + plotW, gy);
    ctx.stroke();
    ctx.fillText(String(yy), plotX0 - 9, gy);
  }
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  for (var xx = 0; xx <= 2.001; xx += 0.5) {
    var gx = px(xx);
    ctx.beginPath();
    ctx.moveTo(gx, plotY0);
    ctx.lineTo(gx, plotY0 + plotH);
    ctx.stroke();
    ctx.fillText(xx.toFixed(1), gx, plotY0 + plotH + 12);
  }

  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(1, Math.min(plotW, plotH) * 0.0042);
  ctx.beginPath();
  ctx.moveTo(plotX0, plotY0);
  ctx.lineTo(plotX0, plotY0 + plotH);
  ctx.lineTo(plotX0 + plotW, plotY0 + plotH);
  ctx.stroke();

  ctx.font = Math.max(14, Math.min(22, plotH * 0.052)) + 'px Arial';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#111';
  ctx.fillText('pH', plotX0 - 45, plotY0 + plotH / 2);

  ctx.font = Math.max(12, Math.min(18, plotW * 0.043)) + 'px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Equivalents of HO−', plotX0 + plotW / 2, plotY0 + plotH + 37);

  ctx.strokeStyle = '#ff0099';
  ctx.lineWidth = Math.max(1.6, Math.min(plotW, plotH) * 0.006);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.beginPath();
  for (var i = 0; i <= 520; i++) {
    var eq = 2 * i / 520;
    var ph = pHFromEq(eq);
    var cx = px(eq), cy = py(ph);
    if (i === 0) ctx.moveTo(cx, cy);
    else ctx.lineTo(cx, cy);
  }
  ctx.stroke();

  var labelFont = Math.max(10, Math.min(16, plotW * 0.039));
  var landmarks = [
    { id: 'pKa1', eq: 0.5, ph: PKA1, label: 'pKₐ1 = 2.34', lx: px(0.055), ly: py(3.12), popup: 'At pKa1, the carboxyl group is half deprotonated. Fully protonated alanine and the zwitterion are present in equal amounts.' },
    { id: 'pI', eq: 1.0, ph: PI, label: 'Isoelectric\npoint = 6.01', lx: px(0.43), ly: py(7.15), popup: 'The isoelectric point is not a 50:50 mixture point. It is where the neutral zwitterion dominates, with +1 and −1 internal charges canceling to net zero.' },
    { id: 'pKa2', eq: 1.5, ph: PKA2, label: 'pKₐ2 = 9.69', lx: px(1.05), ly: py(10.9), popup: 'At pKa2, the ammonium group is half deprotonated. The zwitterion and the fully deprotonated anion are present in equal amounts.' }
  ];

  landmarks.forEach(function (lm) {
    var x = px(lm.eq), y = py(lm.ph);
    if (showLinkedHighlight && selectedLandmark === lm.id) {
      ctx.save();
      ctx.strokeStyle = 'rgba(255,0,153,0.34)';
      ctx.lineWidth = Math.max(4, plotW * 0.014);
      ctx.beginPath();
      ctx.arc(x, y, Math.max(5, plotW * 0.020), 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
    ctx.strokeStyle = '#111';
    ctx.lineWidth = Math.max(0.9, plotW * 0.003);
    var xr = Math.max(4, plotW * 0.013);
    ctx.beginPath();
    ctx.moveTo(x - xr, y - xr); ctx.lineTo(x + xr, y + xr);
    ctx.moveTo(x + xr, y - xr); ctx.lineTo(x - xr, y + xr);
    ctx.stroke();

    if (lm.id === 'pKa1') drawAnnotationArrow(ctx, lm.lx + 62, lm.ly + 2, x - 5, y - 1);
    if (lm.id === 'pI') drawAnnotationArrow(ctx, lm.lx + 55, lm.ly + 6, x - 5, y - 1);
    if (lm.id === 'pKa2') drawAnnotationArrow(ctx, lm.lx + 45, lm.ly + 3, x - 4, y - 1);

    if (lm.label.indexOf('\n') >= 0) {
      drawTextHalo(ctx, 'Isoelectric', lm.lx, lm.ly - labelFont * 0.58, '#111', labelFont + 'px Arial', 'left');
      drawTextHalo(ctx, 'point = 6.01', lm.lx, lm.ly + labelFont * 0.65, '#111', labelFont + 'px Arial', 'left');
    } else {
      drawTextHalo(ctx, lm.label, lm.lx, lm.ly, '#111', labelFont + 'px Arial', 'left');
    }
    hitRegions.push({ type: 'landmark', id: lm.id, x: x - 14, y: y - 14, w: 28, h: 28, text: lm.label.replace('\n', ' '), popup: lm.popup, eq: lm.eq });
  });

  if (showInteractiveMarker) {
    var mPh = pHFromEq(currentEq);
    var mx = px(currentEq), my = py(mPh);
    ctx.save();
    ctx.fillStyle = 'rgba(255,247,168,0.86)';
    ctx.strokeStyle = 'rgba(0,0,0,0.72)';
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.arc(mx, my, Math.max(4, Math.min(6, plotW * 0.014)), 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    var readX = Math.min(plotX0 + plotW - 53, mx + 10);
    var readY = Math.max(plotY0 + 18, my - 13);
    drawTextHalo(ctx, 'pH ' + mPh.toFixed(2), readX, readY, '#111', Math.max(9, Math.min(13, plotW * 0.032)) + 'px Arial', 'left');
  }

  var rowTop = Math.max(plotY0 + 62 * s, py(11.55));
  var rowPka2 = py(9.45);
  var rowPi = py(6.0);
  var rowPka1 = py(2.85);
  var rowLow = Math.min(plotY0 + plotH - 42 * s, py(0.35));
  var ar = activeRegion();
  var singleW = 174 * s, singleH = 124 * s;
  var pairW = 350 * s, pairH = 126 * s;

  drawLeader(ctx, px(0.02), py(0.05), singleX - 8 * s, rowLow, ar === 'low');
  drawLeader(ctx, px(0.56), py(PKA1), pairX - 9 * s, rowPka1, ar === 'pKa1');
  drawLeader(ctx, px(1.02), py(PI), singleX - 8 * s, rowPi, ar === 'pI');
  drawLeader(ctx, px(1.52), py(PKA2), pairX - 9 * s, rowPka2, ar === 'pKa2');
  drawLeader(ctx, px(2.0), py(11.55), singleX - 8 * s, rowTop, ar === 'high');

  if (netChargeView) {
    var cw = Math.min(rightW - 10, 365 * s), ch = 58 * s;
    var cardX = rightX + Math.max(4, rightW * 0.05);
    drawChargeCard(ctx, cardX, rowTop - ch / 2, cw, ch, 'Fully deprotonated', 'H2NCH(CH3)COO−', '−1', showLinkedHighlight && ar === 'high', s);
    drawChargeCard(ctx, cardX, rowPka2 - ch / 2, cw, ch, 'pKa2 mixture', '50:50 net 0 and −1 forms', '½', showLinkedHighlight && ar === 'pKa2', s);
    drawChargeCard(ctx, cardX, rowPi - ch / 2, cw, ch, 'Isoelectric zwitterion', '+ and − internal charges cancel', '0', showLinkedHighlight && ar === 'pI', s);
    drawChargeCard(ctx, cardX, rowPka1 - ch / 2, cw, ch, 'pKa1 mixture', '50:50 net +1 and 0 forms', '½', showLinkedHighlight && ar === 'pKa1', s);
    drawChargeCard(ctx, cardX, rowLow - ch / 2, cw, ch, 'Fully protonated', 'H3N+CH(CH3)COOH', '+1', showLinkedHighlight && ar === 'low', s);
  } else {
    if (showLinkedHighlight && ar === 'high') drawSpeciesGroupHighlight(ctx, singleX - 7 * s, rowTop - 73 * s, singleW, singleH, 'blue', s);
    drawBracket(ctx, singleX, rowTop - 72 * s, 166 * s, 126 * s, s);
    drawAlanine(ctx, singleX + 16 * s, rowTop, 'deprot', s);
    hitRegions.push({ type: 'species', x: singleX, y: rowTop - 72 * s, w: 166 * s, h: 126 * s, text: 'Fully deprotonated alanine: H2NCH(CH3)COO−, net −1.' });

    if (showLinkedHighlight && ar === 'pKa2') drawSpeciesGroupHighlight(ctx, pairX - 7 * s, rowPka2 - 72 * s, pairW, pairH, 'magenta', s);
    drawBracket(ctx, pairX, rowPka2 - 72 * s, 340 * s, 126 * s, s);
    drawAlanine(ctx, pairX + 15 * s, rowPka2, 'zwitter', s);
    ctx.fillStyle = '#111';
    ctx.font = (20 * s) + 'px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('+', pairX + 172 * s, rowPka2 - 5 * s);
    drawAlanine(ctx, pairX + 204 * s, rowPka2, 'deprot', s);
    hitRegions.push({ type: 'species', x: pairX, y: rowPka2 - 72 * s, w: 340 * s, h: 126 * s, text: 'pKa2: a 50:50 mixture of zwitterionic alanine and fully deprotonated alanine.' });

    if (showLinkedHighlight && ar === 'pI') drawSpeciesGroupHighlight(ctx, singleX - 7 * s, rowPi - 72 * s, singleW, singleH, 'magenta', s);
    drawBracket(ctx, singleX, rowPi - 72 * s, 166 * s, 126 * s, s);
    drawAlanine(ctx, singleX + 16 * s, rowPi, 'zwitter', s);
    hitRegions.push({ type: 'species', x: singleX, y: rowPi - 72 * s, w: 166 * s, h: 126 * s, text: 'Zwitterionic alanine: internal + and − charges cancel, giving net charge 0.' });

    if (showLinkedHighlight && ar === 'pKa1') drawSpeciesGroupHighlight(ctx, pairX - 7 * s, rowPka1 - 72 * s, pairW, pairH, 'magenta', s);
    drawBracket(ctx, pairX, rowPka1 - 72 * s, 340 * s, 126 * s, s);
    drawAlanine(ctx, pairX + 15 * s, rowPka1, 'full', s);
    ctx.fillStyle = '#111';
    ctx.font = (20 * s) + 'px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('+', pairX + 172 * s, rowPka1 - 5 * s);
    drawAlanine(ctx, pairX + 204 * s, rowPka1, 'zwitter', s);
    hitRegions.push({ type: 'species', x: pairX, y: rowPka1 - 72 * s, w: 340 * s, h: 126 * s, text: 'pKa1: a 50:50 mixture of fully protonated alanine and zwitterionic alanine.' });

    if (showLinkedHighlight && ar === 'low') drawSpeciesGroupHighlight(ctx, singleX - 7 * s, rowLow - 72 * s, singleW, singleH, 'magenta', s);
    drawBracket(ctx, singleX, rowLow - 72 * s, 166 * s, 126 * s, s);
    drawAlanine(ctx, singleX + 16 * s, rowLow, 'full', s);
    hitRegions.push({ type: 'species', x: singleX, y: rowLow - 72 * s, w: 166 * s, h: 126 * s, text: 'Fully protonated alanine: H3N+ and COOH, net +1.' });
  }
}

var alaninePlugin = {
  id: 'alanineTitrationCustom',
  afterDraw: function (chartInstance) {
    drawFigure(chartInstance);
  }
};

chart = new Chart(canvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: { x: { display: false, min: 0, max: 2 }, y: { display: false, min: 0, max: 12 } }
  },
  plugins: [alaninePlugin]
});
window.__markRendered();

canvas.addEventListener('mousemove', function (e) {
  var r = canvas.getBoundingClientRect();
  var x = e.clientX - r.left, y = e.clientY - r.top;
  var hit = null;
  for (var i = hitRegions.length - 1; i >= 0; i--) {
    var h = hitRegions[i];
    if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h) { hit = h; break; }
  }
  if (hit) {
    canvas.style.cursor = 'pointer';
    showTooltip(hit.text, e);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
  }
});

canvas.addEventListener('mouseleave', function () {
  canvas.style.cursor = 'default';
  hideTooltip();
});

canvas.addEventListener('click', function (e) {
  var r = canvas.getBoundingClientRect();
  var x = e.clientX - r.left, y = e.clientY - r.top;
  for (var i = hitRegions.length - 1; i >= 0; i--) {
    var h = hitRegions[i];
    if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h) {
      if (h.type === 'landmark') {
        selectedLandmark = h.id;
        currentEq = h.eq;
        showInteractiveMarker = true;
        showLinkedHighlight = true;
        var slider = document.getElementById('baseEquivalentsInput');
        if (slider) slider.value = currentEq;
        var out = document.getElementById('baseEquivalentsVal');
        if (out) out.value = currentEq.toFixed(2);
        chart.update('none');
        showPopup(h.text, h.popup);
      } else {
        showLinkedHighlight = true;
        selectedLandmark = activeRegion();
        chart.update('none');
        showPopup('Alanine form', h.text + ' Moving the base-equivalents slider shifts which form or mixture is linked to the titration curve.');
      }
      return;
    }
  }
});

document.addEventListener('fig-resize', function () {
  if (chart) chart.resize();
});

goToStep(0, true);
